class Solution(object):
    def largestNumber(self, nums):
        """
        :type nums: List[int]
        :rtype: str
        """
        def cmp(num1, num2):
            str1 = num1 + num2
            str2 = num2 + num1
            if str1 > str2:
                return 1
            elif str1 == str2:
                return 0
            else:
                return -1

        str_nums = list(map(lambda x:str(x), nums))
        str_nums.sort(key=functools.cmp_to_key(cmp), reverse=True)
        ans = "".join(str_nums)
        return "0" if ans[0] == "0" else ans
